SELECT DISTINCT    T1.[CardCode] AS 'BP Code',     T1.[CardFName] AS 'Foreign Name',     T1.[CardName] AS 'BP Name',     T1.[CardType] AS 'BP Type',     T1.[DflAccount] AS 'Default Account',     T1.[Address] AS 'Bill-to Street',     T1.[Currency] AS 'BP Currency',     T1.[LicTradNum] AS 'Federal Tax ID',     T1.[MailAddres] AS 'Ship-to Street',     T2.[PymntGroup] AS 'Payment Terms Code',     T2.[ExtraDays] AS 'Number of Additional Days',     T3.[GroupName] AS 'Group Name' FROM [dbo].[OCRD] T1  -- Đưa bảng chính OCRD (Master Data) lên đầu để dễ nhìnINNER JOIN [dbo].[OCTG] T2 ON T2.[GroupNum] = T1.[GroupNum]  -- Kết nối điều khoản thanh toánINNER JOIN [dbo].[OCRG] T3 ON T3.[GroupCode] = T1.[GroupCode] -- Kết nối nhóm khách hàng (Đã sửa lỗi ở đây)LEFT JOIN [dbo].[CRD1] T0 ON T0.[CardCode] = T1.[CardCode]  -- Kết nối bảng địa chỉ (Dùng LEFT JOIN nếu có khách hàng chưa có địa chỉ)